// === 1. Quiz Data (Base64 Encoded) ===
const QUIZ_DATA_ENCODED = ""

let statsSessione = {
    totali: 0,
    esatte: 0,
    errate: 0
};

function creaHtmlStats() {
    const percentuale = statsSessione.totali > 0 
        ? Math.round((statsSessione.esatte / statsSessione.totali) * 100) 
        : 0;

    // Logica per l'idoneità (10 domande superate)
    const sogliaRaggiunta = statsSessione.esatte >= 10;

    return `
        <div class="stats-allenamento">
            <div class="stats-item">Domande <span class="stats-value">${statsSessione.totali}</span></div>
            <div class="stats-item">Esatte <span class="stats-value" style="color: #15803d;">${statsSessione.esatte}</span></div>
            <div class="stats-item">Errate <span class="stats-value" style="color: #b91c1c;">${statsSessione.errate}</span></div>
            <div class="stats-item">Percentuale esatte <span class="stats-value">${percentuale}%</span></div>
        </div>
    `;
}

// === 2. Decodifica dati (senza fetch) === 
function caricaDatiLocali() {
    const binary = atob(QUIZ_DATA_ENCODED);
    const bytes = Uint8Array.from(binary, c => c.charCodeAt(0));
    const jsonString = pako.inflate(bytes, { to: "string" });
    return JSON.parse(jsonString);
}

// === 3. Mostra elenco schede === 
function mostraElencoSchede(schede) {
    const container = document.getElementById("container-app");
    const intro = document.getElementById("container-introduzione");

    // Pulisce il contenitore e resetta lo scroll
    container.innerHTML = "";
    window.scrollTo(0, 0);

    // Creazione barra di navigazione (Home | Allenamento)
    const navHeader = document.createElement("div");
    navHeader.className = "nav-header";
    
    // Titolo della sezione
    const titolo = document.createElement("h2");
    titolo.textContent = "Seleziona una scheda";
    container.appendChild(titolo);

    // Pulsante Home
    const btnHome = document.createElement("button");
    btnHome.className = "btn-nav";
    btnHome.textContent = "🏠 Home";
    btnHome.onclick = () => {
        container.style.display = "none";
        intro.style.display = "block";
        window.scrollTo(0, 0);
    };

    // Pulsante Allenamento (Top)
    const btnAllenamentoTop = document.createElement("button");
    btnAllenamentoTop.className = "btn-nav btn-nav-allenamento";
    btnAllenamentoTop.textContent = "🧠 Allenamento";
    btnAllenamentoTop.onclick = () => {
        container.innerHTML = ""; // Cancella il contenuto attuale
        mostraDomandaCasuale();  
    };

    navHeader.appendChild(btnHome);
    navHeader.appendChild(btnAllenamentoTop);
    container.appendChild(navHeader);

    // 4. Creazione Elenco Schede
    const wrapperSchede = document.createElement("div");
    wrapperSchede.className = "lista-pulsanti-schede";

    schede.forEach(s => {
        const btn = document.createElement("button");
        btn.className = "scheda-btn"; // Usa la classe definita nel CSS
        btn.textContent = s.titolo;
        btn.onclick = () => {
            window.scrollTo(0, 0);
            mostraScheda(s);
        };
        wrapperSchede.appendChild(btn);
    });

    container.appendChild(wrapperSchede);
}

// === 3 ter. Mostra una domanda casuale ===
function mostraDomandaCasuale() {

    // Controllo di sicurezza: assicurati che le domande siano caricate
    if (!window._tutteLeDomande || window._tutteLeDomande.length === 0) {
        alert("Errore di sistema: nessuna domanda caricata.");
        return;
    }

    const app = document.getElementById("container-app");
    app.innerHTML = "";

    // Estrai una domanda casuale
    const tutte = window._tutteLeDomande; 
    const domanda = tutte[Math.floor(Math.random() * tutte.length)];

    // Contenitore domanda
    const box = document.createElement("div");
    box.className = "domanda-box";
    app.appendChild(box);

    // Titolo sezione
    const sezione = document.createElement("h2");
    sezione.textContent = "Domanda Casuale";
    const subtitle = document.createElement("span");
    subtitle.innerHTML = '<br><i>Scegli la voce che ritieni corretta e clicca su "Verifica" per il riscontro.</i>';
    subtitle.className = "domanda-box-subtitle"
    sezione.appendChild(subtitle);
    box.appendChild(sezione);

    // Testo domanda
    const titolo = document.createElement("h3");
    titolo.textContent = domanda.testo;
    box.appendChild(titolo);

    // Immagine (se presente)
    if (domanda.immagine) {
        const img = document.createElement("img");
        img.src = domanda.immagine;
        img.className = "domanda-img";
        box.appendChild(img);
    }

    // Risposte
    const form = document.createElement("div");
    form.className = "risposte-container";
    box.appendChild(form);

    domanda.risposte.forEach((r, idx) => {
        const label = document.createElement("label");
        label.className = "risposta-radio";

        const radio = document.createElement("input");
        radio.type = "radio";
        radio.name = "risposta";
        radio.value = idx;

        label.appendChild(radio);
        const testo = document.createElement("span");
        testo.textContent = r;
        label.appendChild(testo);

        form.appendChild(label);
    });

    // Statistiche sessione
    const stats = document.createElement("div");
    stats.id = "box-statistiche-sessione";
    stats.innerHTML = creaHtmlStats();
    box.appendChild(stats);

    // Pulsante verifica
    const btnVerifica = document.createElement("button");
    btnVerifica.className = "scheda-btn allenamento-btn";
    btnVerifica.textContent = "🔍Verifica";
    btnVerifica.onclick = () => verificaRispostaAllenamento(domanda);
    app.appendChild(btnVerifica);

    // Pulsante home
    const btnHome = document.createElement("button");
    btnHome.className = "scheda-btn allenamento-btn";
    btnHome.textContent = "🏠 Torna alla home";
    btnHome.onclick = () => renderHome();
    app.appendChild(btnHome);
}

// === 3 quater. Mostra corretto/errato e offre "Nuova domanda" o "Torna alla Home" ===
function verificaRispostaAllenamento(domanda) {
    const app = document.getElementById("container-app");
    const selezionata = document.querySelector("input[name='risposta']:checked");

    if (!selezionata) {
        alert("Seleziona una risposta prima di verificare.");
        return;
    }

    const indice = parseInt(selezionata.value, 10);
    
    // Aggiorna statistiche sessione
    statsSessione.totali++;
    if (indice === domanda.corretta) {
        statsSessione.esatte++;
    } else {
        statsSessione.errate++;
    }
    const boxStat = document.getElementById("box-statistiche-sessione");
    if (boxStat) {
        boxStat.innerHTML = creaHtmlStats();
        
        // Una piccola animazione per far notare il cambio
        boxStat.style.animation = "none";
        setTimeout(() => boxStat.style.animation = "fade-in 0.3s ease", 10);
    }

    // Evidenziazione corretta/errata
    const labels = document.querySelectorAll(".risposta-radio");

    labels.forEach((label, idx) => {
        label.classList.remove("corretta", "errata");

        if (idx === domanda.corretta) {
            label.classList.add("corretta");
        }

        if (idx === indice && indice !== domanda.corretta) {
            label.classList.add("errata");
        }
    });

    // Disabilita tutte le opzioni dopo la verifica
    const radios = document.querySelectorAll("input[name='risposta']");
    radios.forEach(r => r.disabled = true);

    // Rimuove eventuale pulsante "Nuova domanda" già presente
    const esistente = document.getElementById("btn-nuova-domanda");
    if (esistente) esistente.remove();

    // Crea il pulsante "Nuova domanda"
    const btnNext = document.createElement("button");
    btnNext.id = "btn-nuova-domanda";
    btnNext.className = "scheda-btn"   // "scheda-btn allenamento-btn";
    btnNext.textContent = "🆕 Nuova domanda";
    btnNext.onclick = () => mostraDomandaCasuale();
    app.appendChild(btnNext);
}

// === 3 quinquies. Funzione per tornare alla home ===
function renderHome() {
    if (!window._schede) {
        alert("Errore di sistema: nessuna scheda caricata.");
        return;
    }
    //mostraElencoSchede(window._schede);
    const intro = document.getElementById('container-introduzione');
    const app = document.getElementById('container-app');
    intro.style.display = 'block';
    app.style.display = 'none'; 
    setTimeout(() => {
        window.scrollTo(0, 0);
        document.documentElement.scrollTop = 0; // Backup per alcuni browser
        document.body.scrollTop = 0;            // Backup per Safari
    }, 10);
}

// === 4. Mostra una scheda (15 domande) === 
function mostraScheda(scheda) {
    const container = document.getElementById("container-app");
    container.innerHTML = `<h2>${scheda.titolo}</h2>`;

    const form = document.createElement("form");
    form.id = "quizForm";

    const msg = document.createElement("p");
    msg.id = "msgErrore";
    msg.style.color = "red";
    msg.style.display = "none";
    msg.textContent = "Devi rispondere a tutte le domande prima di inviare.";
    form.appendChild(msg);

    scheda.domande.forEach((d, idx) => {
        const div = document.createElement("div");
        div.style.marginBottom = "20px";

        div.innerHTML = `<p><strong>${idx + 1}. ${d.testo}</strong></p>`;

    if (d.immagine) {
        const box = document.createElement("div");
        box.className = "question-image-box";

        const img = document.createElement("img");
        img.src = d.immagine;

        box.appendChild(img);
        div.appendChild(box);
    }

        d.risposte.forEach((r, i) => {
            const id = `q${idx}_r${i}`;

            const label = document.createElement("label");
            label.htmlFor = id;
            label.style.display = "block";

            const input = document.createElement("input");
            input.type = "radio";
            input.name = `q${idx}`;
            input.value = i;
            input.id = id;

            label.appendChild(input);
            label.appendChild(document.createTextNode(" " + r));

            div.appendChild(label);
        });

        form.appendChild(div);
    });

    const btn = document.createElement("button");
    btn.type = "submit";
    btn.textContent = "Controlla risposte";
    btn.style.padding = "10px 20px";
    btn.style.fontSize = "16px";
    form.appendChild(btn);

    const btnAnnulla = document.createElement("button");
    btnAnnulla.textContent = "Annulla";
    btnAnnulla.style.marginLeft = "10px";
    btnAnnulla.onclick = () => mostraElencoSchede(window._schede);
    form.appendChild(btnAnnulla);

    form.onsubmit = (e) => {
        e.preventDefault();

        const risposteUtente = [];
        let tutteRisposte = true;

        scheda.domande.forEach((d, idx) => {
            const risposta = form.querySelector(`input[name="q${idx}"]:checked`);

            // scroll dolce verso l'alto subito dopo il submit
            window.scrollTo({ top: 0, behavior: "smooth" });    

            if (!risposta) {
                tutteRisposte = false;
            } else {
                risposteUtente.push(parseInt(risposta.value));
            }
        });

        if (!tutteRisposte) {
            msg.style.display = "block";
            return;
        }

        mostraRiepilogo(scheda, risposteUtente);
    };

    container.appendChild(form);
}

// === 5. Riepilogo finale dettagliato === 
function mostraRiepilogo(scheda, risposteUtente) {
    let corrette = 0;
    const container = document.getElementById("container-app");

    let html = `
        <h2>Riepilogo – ${scheda.titolo}</h2>
        <p style="font-size:17px; margin-bottom:20px;">
            Risposte corrette: <strong id="score"></strong>
        </p>
    `;

    html += `<div>`;

    scheda.domande.forEach((d, idx) => {
        const idxUtente = risposteUtente[idx];
        const idxCorretta = d.corretta;

        const testoUtente = d.risposte[idxUtente];
        const testoCorretta = d.risposte[idxCorretta];

        const esatta = idxUtente === idxCorretta;
        if (esatta) corrette++;

        html += `
            <div class="question-summary">
                <p><strong>${idx + 1}. ${d.testo}</strong></p>
        `;

        if (d.immagine) {
            html += `
                <img src="${d.immagine}" style="max-width:300px; display:block; margin:10px 0;">
            `;
        }

        html += `
                <p>
                    Tua risposta:
                    <span class="${esatta ? 'answer-correct' : 'answer-wrong'}">
                        ${testoUtente}
                    </span>
                    <span class="answer-icon">${esatta ? '✔' : '✘'}</span>
                </p>
        `;

        if (!esatta) {
            html += `
                <p>
                    Risposta corretta:
                    <span class="answer-correct">${testoCorretta}</span>
                </p>
            `;
        }

        html += `</div>`;
    });

    html += `</div>`;

    container.innerHTML = html;

    // Inseriamo il punteggio ora che è calcolato
    document.getElementById("score").textContent =
        `${corrette} / ${scheda.domande.length}`;

    // Pulsante per tornare alle schede
    const btn = document.createElement("button");
    btn.textContent = "Torna alle schede";
    btn.onclick = () => mostraElencoSchede(window._schede);
    btn.style.marginTop = "20px";
    btn.style.padding = "10px 20px";
    btn.style.fontSize = "16px";
    container.appendChild(btn);
}

// === 6. Avvio === 
window.addEventListener('load', function() {
    const data = caricaDatiLocali();
    window._tutteLeDomande = data.schede.flatMap(s => s.domande); // per modalità allenamento
    window._schede = data.schede;

    const btnSchede = document.getElementById('schede-btn');
    const btnAllenamento = document.getElementById('training-mode-btn');
    const intro = document.getElementById('container-introduzione');
    const app = document.getElementById('container-app');

    // Aggiunge l'evento al click
    btnSchede.addEventListener('click', function() {
        intro.style.display = 'none';
        app.style.display = 'block'; 
        setTimeout(() => {
            window.scrollTo(0, 0);
            document.documentElement.scrollTop = 0; // Backup per alcuni browser
            document.body.scrollTop = 0;            // Backup per Safari
        }, 10);
        mostraElencoSchede(data.schede);
    });

    btnAllenamento.addEventListener('click', function() {
        intro.style.display = 'none';
        app.style.display = 'block';
        setTimeout(() => { 
            window.scrollTo(0, 0);
            document.documentElement.scrollTop = 0; // Backup per alcuni browser
            document.body.scrollTop = 0;            // Backup per Safari
        }, 10);
        statsSessione = { totali: 0, esatte: 0, errate: 0 }; // Reset stats
        mostraDomandaCasuale();  
    });
});